    "html": "<p>日本人の天気の話</p><p>アルティカミラ</p><p>日本へ来て、多くの人が天気の話をすることに気がつきました。アパートの管理人さんは、朝会うと、「おはよう」の後に「今日は暑いね」とか「いい天気だね」と言います。あちこちで、多くの人があいさつに続けて天気の話をしているのを聞きました。<span class='p-anchor' data-qid='gpm3_lt1_p2_q2'>（ 2 ）</span>、私の国では天気の話をあまりしないので、なぜ天気の話をするのかわかりませんでした。私はしてもしなくてもいいと考え、自分から話していませんでした。</p>",
