    "html": "<p>掃除の時間</p><p>ヒダヤティネニ</p><p>教室で子供たちとゲームをして、そこで一緒に昼ご飯を食べました。食べ終わって話していたとき、掃除の時間を知らせる放送が流れました。<span class='p-anchor' data-qid='gpm3_lt1_p3_q3'>（ 3 ）</span>、予想外のことが起きました。子供たちが教室の前に机といすを運び始めたのです。</p>",
