    "title": "Liên từ chuyên sâu #4 — 東京での一人暮らし (Sống một mình ở Tokyo)",
    "kind": "cloze",
    "html": "<p>ぼくはこの春、希望の大学に合格し東京で一人暮らしを始めることになった。</p><p>ぼくは4人兄弟で、家の中はいつもにぎやかだったので、早く自分だけの静かな時間がほしいと思っていた。<span class='p-anchor' data-qid='gpm3_lt2_p4_q4'>（ 4 ）</span>、東京に出てくるときは、夢のような気分だった。一人暮らしなら、たとえ昼過ぎまで寝ていても、夜どんなに遅くまで起きていても、文句を言う人などいないのだ。</p>",
