    "kind": "cloze",
    "html": "<p>しかし、働きながら勉強するのは簡単なことではありません。勉強の時間を作るために、皆さん、いろいろな工夫や努力をしていることがわかりました。</p><p><span class='p-anchor' data-qid='gpm3_lt2_p5_q5'>（ 5 ）</span>、毎朝4時に起きて勉強している人や、出勤時間まで会社の近くの喫茶店で勉強するなど、朝の時間を活用している人もたくさんいました。</p>",
