    "topic": "Liên từ (Chuyên sâu)",
    "title": "Liên từ chuyên sâu #9 — レポートの締め切り相談 (Xin gia hạn nộp báo cáo)",
    "kind": "cloze",
    "html": "<p>学生：先生、今よろしいでしょうか。レポートのことでお願いがあるんですが…。</p><p>先生：ああ、佐藤君。レポートは「選挙と投票率について」だったね。<span class='p-anchor' data-qid='gpm3_lt2_p9_q13'>（ 13 ）</span>？</p><p>学生：あのう、あと3枚で完成するんです。<span class='p-anchor' data-qid='gpm3_lt2_p9_q14'>（ 14 ）</span>、あのう、締め切りが今日の5時までなので間に合いそうもないんです。<span class='p-anchor' data-qid='gpm3_lt2_p9_q15'>（ 15 ）</span>、あと1日あれば、必ず出せます。</p><p>先生：あと3枚か。わかった。明日の午前9時までに必ずここに持ってきなさい。</p>",
